'use strict';
const $ = s => document.querySelector(s);
const escapeHTML = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e = escapeHTML;
const S = {session:null, overview:null, module:null, clientId:'', view:'direction', filter:'', loading:0};
const icons = {
  grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',
  wallet:'M3 5h16v4M3 5v14h18V9H3V5Zm12 7h6v4h-6z', users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M18 8a3 3 0 0 1 0 6M22 21v-2a4 4 0 0 0-3-3',
  check:'m5 12 4 4L19 6', work:'M4 5h16v16H4zM8 3v4M16 3v4M4 10h16M8 14h3M8 18h7', growth:'m3 17 6-6 4 4 8-10M15 5h6v6', card:'M3 4h18v16H3zM3 9h18M7 15h4', agents:'M8 5h8v3H8zM5 8h14v12H5zM9 12v2M15 12v2M9 17h6M12 2v3M2 12h3M19 12h3',
  approval:'M8 3h8l4 4v14H4V3h4m0 0v5h8V3m-8 12 3 3 5-6', clock:'M12 8v5l3 2M22 12a10 10 0 1 0-20 0 10 10 0 0 0 20 0', book:'M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3zM12 6v16', link:'m10 13 4-4M8 15l-2 2a3 3 0 0 1-4-4l5-5a3 3 0 0 1 4 0M13 11a3 3 0 0 0 4 0l5-5a3 3 0 0 0-4-4l-2 2', eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12ZM15 12a3 3 0 1 0-6 0 3 3 0 0 0 6 0',
  plus:'M12 5v14M5 12h14', arrow:'M5 12h14m-5-5 5 5-5 5', close:'m6 6 12 12M18 6 6 18', menu:'M3 6h18M3 12h18M3 18h18', refresh:'M20 7a9 9 0 1 0 1 7M20 3v5h-5', mail:'M3 5h18v14H3zM3 5l9 8 9-8', search:'M21 21l-6-6M17 9a8 8 0 1 0-16 0 8 8 0 0 0 16 0', info:'M12 11v6M12 7v1M22 12a10 10 0 1 0-20 0 10 10 0 0 0 20 0', play:'m8 4 12 8-12 8z', pause:'M7 4v16M17 4v16', logout:'M9 4H3v16h6M9 12h12m-5-5 5 5-5 5', file:'M4 3h11l5 5v13H4zM14 3v6h6M8 13h8M8 17h6', shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6zM8 12l3 3 5-6', calendar:'M3 5h18v16H3zM7 2v6M17 2v6M3 10h18', star:'m12 2 3 7 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z', bolt:'m13 2-9 12h7l-1 8 10-13h-7z', chart:'M4 21V12M11 21V3M18 21V8', globe:'M21 12H3M12 2c7 7 7 13 0 20-7-7-7-13 0-20ZM22 12a10 10 0 1 0-20 0 10 10 0 0 0 20 0'
};
const icon = name => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name] || icons.grid}"/></svg>`;
const money = n => n === null || n === undefined ? '—' : new Intl.NumberFormat('it-IT',{style:'currency',currency:'EUR',maximumFractionDigits:2}).format(n / 100);
const date = (v, time=false) => v ? new Intl.DateTimeFormat('it-IT',time?{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}:{day:'2-digit',month:'short',year:'numeric'}).format(new Date(v)) : '—';
const today = () => new Date().toISOString().slice(0,10);
const localInput = value => {const d=new Date(value);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}T${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;};
const cents = value => { const raw=String(value).trim().replace(',','.');if(!/^-?\d+(?:\.\d{1,2})?$/.test(raw))throw Error('Inserisci un importo valido con al massimo due decimali.');const negative=raw.startsWith('-'),parts=raw.replace(/^-/,'').split('.'),result=Number(parts[0])*100+Number((parts[1]||'').padEnd(2,'0'));if(!Number.isSafeInteger(result))throw Error('Importo troppo grande.');return negative?-result:result; };
const role = () => S.session?.user?.role;
const isOwner = () => role() === 'owner';
const canProduce = () => role() !== 'client';
const serviceName = id => S.overview?.registry?.services?.find(x=>x.id===id)?.name || id;
const activeServices = () => (S.overview?.currentClientServices || JSON.parse(S.overview?.currentClient?.services_json || '[]')).map(x=>typeof x==='string'?x:x.id);
const clientName = id => S.overview?.clients?.find(c=>c.id===id)?.name || S.overview?.currentClient?.name || 'Attività DEMO';
const statusNames = {new:'Nuovo',qualified:'Qualificato',contacted:'Contattato',interested:'Interessato',meeting:'Appuntamento',proposal:'Proposta',won:'Acquisito',lost:'Chiuso',draft:'Bozza',approved:'Approvato',cancelled:'Annullato',queued:'In coda',running:'In corso',done:'Completato',failed:'Da verificare',pending:'Da approvare',blocked:'Bloccato',todo:'Da fare',doing:'In corso',simulated_sent:'Invio simulato',simulated_booked:'Appuntamento DEMO',uncertain:'Esito da verificare',received:'Ricevuto DEMO',handled:'Gestito',needs_owner:'Serve un socio',open:'Aperta',in_review:'In verifica',resolved:'Risolta',rejected:'Rifiutato',changes:'Modifiche richieste',awaiting_approval:'In approvazione',prepared:'Preparata',stamps:'Timbri',points:'Punti',coupon:'Coupon',credit:'Accredito',redeem:'Premio riscattato',reversal:'Storno',active:'Attivo',inactive:'Inattivo',all:'Tutti',reward:'Premio disponibile',normal:'Regolare',high:'Alta',critical:'Urgente',medium:'Media',implemented:'Disponibile DEMO',planned:'Da attivare',module:'Modulo disponibile'};
const label = v => statusNames[v] || v || '—';
function badge(value, tone) { const c=tone||(['done','approved','won','resolved','active','APPROVATO'].includes(value)?'green':['failed','critical','uncertain','lost','blocked'].includes(value)?'red':['pending','new','queued','draft','DA APPROVARE','awaiting_approval'].includes(value)?'orange':'');return `<span class="badge ${c}">${e(label(value))}</span>`; }
const btn = (title,action,id='',style='',symbol='') => `<button class="btn ${style}" data-action="${e(action)}" ${id?`data-id="${e(id)}"`:''}>${symbol?icon(symbol):''}${e(title)}</button>`;
const empty = (title,description='',symbol='grid') => `<div class="empty">${icon(symbol)}<strong>${e(title)}</strong><p>${e(description)}</p></div>`;
const notice = (text,orange=false) => `<div class="notice ${orange?'orange':''}">${icon('info')}<p>${e(text)}</p></div>`;
const stat = (title,value,note='',symbol='chart',emphasis=false) => `<article class="stat ${emphasis?'emphasis':''}"><div class="stat-label">${e(title)}${icon(symbol)}</div><div class="stat-value">${e(value)}</div><div class="stat-note">${e(note)}</div></article>`;
const panel = (title,body,actions='',subtitle='') => `<section class="panel"><div class="panel-head"><div><h2>${e(title)}</h2>${subtitle?`<small>${e(subtitle)}</small>`:''}</div>${actions}</div>${body}</section>`;
const table = (headers,rows) => rows.length ? `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th scope="col">${e(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>` : empty('Ancora nessuna voce','Le nuove attività compariranno qui.');
const list = (items,renderer) => items.length ? `<div class="list">${items.map(renderer).join('')}</div>` : empty('Tutto libero, per ora','Nessuna attività registrata in questa sezione.');
const title = (name,description,actions='') => `<header class="page-head"><div><div class="eyebrow">BigAnt OS / ${e(clientName(S.clientId))}</div><h1>${e(name)}</h1><p>${e(description)}</p></div><div class="actions">${actions}</div></header>`;

async function api(path, {method='GET',body,scoped=true}={}) {
  const u=new URL(path,location.origin); if(scoped&&S.clientId)u.searchParams.set('clientId',S.clientId);
  const headers={Accept:'application/json'};if(body!==undefined)headers['Content-Type']='application/json';if(S.session?.csrf)headers['X-CSRF-Token']=S.session.csrf;
  const response=await fetch(u,{method,headers,credentials:'same-origin',body:body===undefined?undefined:JSON.stringify(body)});
  const contentType=response.headers.get('content-type')||'';
  const result=contentType.includes('application/json')?await response.json():await response.text();
  if(!response.ok)throw new Error(result.error||result.message||'Operazione non riuscita. Riprova.');return result;
}
async function mutate(path,body={},method='POST'){return api(path,{method,body});}
let toastTimer;
function toast(message,error=false){clearTimeout(toastTimer);const el=$('#toast');el.textContent=message;el.className=`toast ${error?'error':''}`;el.hidden=false;toastTimer=setTimeout(()=>el.hidden=true,6500);}
function dialog(titleText,html){$('#dialog-content').innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${e(titleText)}</h2><button class="icon-btn" data-action="close" aria-label="Chiudi finestra">${icon('close')}</button></div><div class="dialog-body">${html}</div>`;if(!$('#dialog').open)$('#dialog').showModal();}
let formHandler=null;
function fieldsHTML(fields){return `<div class="form-grid">${fields.map(f=>{if(f.html)return `<div class="field full">${f.html}</div>`;const id='field-'+f.name,v=f.value??'',required=f.required?'required':'';if(f.type==='checkbox')return `<div class="field full"><label class="check-field"><input type="checkbox" name="${e(f.name)}" ${v?'checked':''}><span>${e(f.label)}</span></label>${f.help?`<small>${e(f.help)}</small>`:''}</div>`;let input=f.type==='textarea'?`<textarea id="${id}" name="${e(f.name)}" ${required}>${e(v)}</textarea>`:f.type==='select'?`<select id="${id}" name="${e(f.name)}" ${required}>${(f.options||[]).map(o=>`<option value="${e(Array.isArray(o)?o[0]:o)}" ${String(Array.isArray(o)?o[0]:o)===String(v)?'selected':''}>${e(Array.isArray(o)?o[1]:label(o))}</option>`).join('')}</select>`:`<input id="${id}" name="${e(f.name)}" type="${f.type||'text'}" value="${e(v)}" ${required} ${f.min!==undefined?`min="${f.min}"`:''} ${f.max!==undefined?`max="${f.max}"`:''} ${f.step?`step="${f.step}"`:''} ${f.placeholder?`placeholder="${e(f.placeholder)}"`:''}>`;return `<div class="field ${f.full?'full':''}"><label for="${id}">${e(f.label)}</label>${input}${f.help?`<small>${e(f.help)}</small>`:''}</div>`;}).join('')}</div>`;}
function form(titleText,fields,handler,{submit='Salva',intro='Solo dati inventati per la prova.',extra=''}={}){const key=crypto.randomUUID();formHandler=async fd=>handler(Object.fromEntries(fd),fd,key);dialog(titleText,`${intro?notice(intro):''}<form id="modal-form"><div class="form-error" role="alert" hidden></div>${fieldsHTML(fields)}${extra}<div class="form-footer">${btn('Annulla','close','','ghost')}<button type="submit" class="btn primary">${e(submit)}</button></div></form>`);}
async function saved(message='Salvato nella demo'){ $('#dialog').close();toast(message);await load(); }
function options(rows,name='name',blank=false){return [...(blank?[['','Nessun collegamento']]:[]),...rows.map(x=>[x.id,x[name]||x.id])];}
function pickServices(selected=[]){return `<label>Servizi attivi</label><div class="service-checks">${(S.overview.registry.services||[]).filter(x=>x.status!=='Escluso').map(s=>`<label><input type="checkbox" name="services" value="${e(s.id)}" ${selected.includes(s.id)?'checked':''}>${e(s.name)}</label>`).join('')}</div>`;}
const approvalItems=()=>isOwner()&&S.overview.agency?S.overview.agency.approvals:S.overview.approvals;
const activityItems=()=>isOwner()&&S.overview.agency?S.overview.agency.activity:S.overview.activity;
const activeOptions=()=>activeServices().map(id=>[id,serviceName(id)]);

const navItems=[['direction','Direzione','grid'],['administration','Amministrazione','wallet'],['clients','Clienti','users'],['work','Lavori e contenuti','work'],['growth','Growth','growth'],['fidelity','Fidelity','card'],['agents','Sciame di agenti','agents'],['approvals','Approvazioni','approval'],['activity','Registro attività','clock'],['catalog','Catalogo servizi','book'],['connections','Collegamenti','link'],['users','Accessi','shield'],['client','Vista cliente','eye']];
function allowedNav(){if(isOwner())return navItems;const permitted=role()==='client'?['client','work','fidelity','approvals']:['work','fidelity','approvals','activity','client'];return navItems.filter(([id])=>permitted.includes(id)&&(id!=='fidelity'||activeServices().includes('fidelity')));}
function shell(content){const current=navItems.find(x=>x[0]===S.view);$('#app').innerHTML=`<div class="shell"><aside class="sidebar" aria-label="Navigazione principale"><a class="brand" href="#direction"><img src="/brand/logo.png" alt="BigAnt Agency"><span class="os">OS</span></a><div class="nav-label">Il tuo spazio di lavoro</div><nav class="nav">${allowedNav().map(([id,name,symbol])=>`${id==='agents'?'<div class="nav-label">Controllo e sistema</div>':''}<button data-view="${id}" class="${S.view===id?'active':''}" ${S.view===id?'aria-current="page"':''}>${icon(symbol)}<span>${name}</span>${id==='approvals'&&(S.overview.agency?.approvalsPending??S.overview.summary.approvalsPending)?`<span class="count">${S.overview.agency?.approvalsPending??S.overview.summary.approvalsPending}</span>`:''}</button>`).join('')}</nav><div class="side-bottom"><div class="side-note"><strong>Piccoli. Con una grande regia.</strong>Tutto il lavoro, un solo posto.<br><span class="dot"> Dati di esempio</span></div><div class="user"><span class="avatar">${e((S.session.user.name||'BA').split(' ').map(x=>x[0]).slice(0,2).join(''))}</span><div><b>${e(S.session.user.name)}</b><small>${isOwner()?'Socio · accesso completo':role()==='client'?'La tua attività':'Team BigAnt'}</small></div></div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Apri menu">${icon('menu')}</button><span>Workspace</span><span>/</span><strong>${e(current?.[1]||'Panoramica')}</strong></div><div class="top-actions"><span class="demo-pill">AMBIENTE DEMO</span><label class="sr-only" for="client-picker">Attività selezionata</label><select id="client-picker" class="client-picker">${S.overview.clients.map(c=>`<option value="${e(c.id)}" ${c.id===S.clientId?'selected':''}>${e(c.name)}</option>`).join('')}</select><button class="icon-btn" data-action="refresh" aria-label="Aggiorna dati">${icon('refresh')}</button><button class="icon-btn" data-action="logout" aria-label="Cambia profilo">${icon('logout')}</button></div></header><main id="main" class="main" tabindex="-1">${content}<footer class="footer-note"><span>BIGANT OS · Forza sproporzionata.</span><span>Dati inventati · Nessun invio, pubblicazione o pagamento esterno.</span></footer></main></div></div>`;}
function login(){const profiles=S.session?.profiles||[];$('#app').innerHTML=`<main class="login"><section class="login-story"><img src="/brand/logo.png" alt="BigAnt Agency"><div><div class="eyebrow">IL SISTEMA OPERATIVO DELL'AGENZIA</div><h1>Piccoli.<br>Con una forza<br><em>sproporzionata.</em></h1><p>Clienti, creatività, agenti e numeri.<br>Finalmente dalla stessa parte.</p></div><footer>BIGANT OS / SPAZIO DI LAVORO INTERNO</footer></section><section class="login-panel" id="main"><span class="demo-pill">ANTEPRIMA INTERATTIVA</span><h2>Entra nel tuo spazio.</h2><p class="muted">Scegli un ruolo per esplorare BigAnt OS. Ogni profilo vede soltanto ciò che gli serve.</p><div class="profiles">${profiles.map(p=>`<button class="profile-button" data-action="login" data-id="${e(p.id)}"><span class="avatar">${icon(p.role==='owner'?'grid':p.role==='client'?'card':'users')}</span><span><b>${e(p.name)}</b><small>${p.role==='owner'?'Controllo completo di agenzia e amministrazione':p.role==='client'?'Servizi, contenuti e approvazioni della propria attività':'Produzione e clienti assegnati'}</small></span>${icon('arrow')}</button>`).join('')||empty('Profili non disponibili','Ricarica la pagina per riprovare.')}</div><button class="btn ghost" data-action="credentials-login">Accedi con un altro utente DEMO</button><p class="footnote">Questa è una prova con dati inventati. Gli account e le fonti esterne sono scollegati. Non servono password personali.</p></section></main>`;}
async function load(){const sequence=++S.loading;try{const overview=await api('/api/overview');if(sequence!==S.loading)return;S.overview=overview;S.clientId=overview.currentClient?.id||overview.clients?.[0]?.id||S.clientId;if(!allowedNav().some(x=>x[0]===S.view))S.view=isOwner()?'direction':role()==='client'?'client':'work';const moduleName={growth:'growth',fidelity:'fidelity',administration:'administration',agents:'agents'}[S.view];S.module=S.view==='users'?await api('/api/users'):moduleName?await api(`/api/${moduleName}/state`):null;if(sequence!==S.loading)return;render();S.lastRefresh=Date.now();}catch(error){toast(error.message,true);if(!S.overview)$('#app').innerHTML=`<main class="loading" id="main">${empty('Non riesco a caricare lo spazio',error.message)}${btn('Riprova','refresh','','primary')}${btn('Cambia profilo','logout')}</main>`;}}
function render(){const views={direction:directionView,administration:administrationView,clients:clientsView,work:workView,growth:growthView,fidelity:fidelityView,agents:agentsView,approvals:approvalsView,activity:activityView,catalog:catalogView,connections:connectionsView,users:usersView,client:clientView};shell((views[S.view]||directionView)()+(S.view==='agents'?moduleJobsPanel():S.view==='administration'?adminExtra():''));}

function directionView(){const o=S.overview,a=o.admin,counts=o.agency||o.summary,questions=a?.questions||[],pending=approvalItems().filter(x=>x.status==='pending');return title('Una regia. Tutta BigAnt.','Il punto su lavori, persone, soldi e prossime decisioni.',`<span class="date-label">${date(new Date())}</span>${btn('Apri le approvazioni','goto','approvals','','approval')}`)+`<section class="hero"><div class="hero-copy"><div class="eyebrow">LA TUA CABINA DI REGIA</div><h2>La testa resta umana.<br>Il lavoro trova il suo ritmo.</h2><p>Controlla ciò che conta, assegna il prossimo passo agli agenti e tieni insieme tutta l'agenzia.</p>${btn('Esplora lo sciame','goto','agents','primary','arrow')}</div><div class="hero-aside"><span class="orbit"></span><span class="orbit second"></span><span class="hero-number">${counts.tasksOpen}</span><small>LAVORI APERTI<br>nel workspace DEMO</small></div></section><div class="stats">${stat('Attività nel sistema',o.summary.clientsActive,'Anagrafiche di esempio','users')}${stat('Lavori in corso',counts.tasksOpen,`${counts.late} oltre scadenza`,'work')}${stat('Decisioni in attesa',counts.approvalsPending,'Il prossimo passo richiede te','approval',true)}${stat('Cassa registrata',a?money(a.summary.balance_cents):'—','Saldi contabili DEMO, da quadrare','wallet')}</div>${o.agency?.priorities?.length?`<div class="section">${panel('Le tre priorità proposte dal Direttore',list(o.agency.priorities,(p,i)=>`<div class="list-item"><span class="number">${i+1}</span><div class="body"><b>${e(p)}</b></div></div>`),badge('DEMO'))}</div>`:''}<div class="section-title"><h2>Le sei domande della settimana</h2><span>Risposte dai dati registrati</span></div><section class="grid-three">${questions.map((q,i)=>`<article class="question"><div class="index">0${i+1} / DIREZIONE</div><h3>${e(q.question)}</h3><div class="answer">${q.valueCents!==undefined?money(q.valueCents):q.items?`${q.items.length} ${q.items.length===1?'voce':'voci'}`:'Da configurare'}</div><small>${e(q.note||q.items?.slice(0,2).map(x=>x.title||serviceName(x.service)||x.name).join(' · ')|| (q.overdueCents!==undefined?`${money(q.overdueCents)} oltre scadenza`:'Nessun elemento segnalato'))}</small></article>`).join('')}</section><div class="grid-two section">${panel('Serve il tuo sguardo',list(pending.slice(0,4),(x,i)=>`<div class="list-item"><span class="number">${i+1}</span><div class="body"><b>${e(x.title)}</b><p>${e(clientName(x.client_id))} · ${x.kind==='growth_message'?'Bozza commerciale':'Contenuto da rivedere'}</p></div>${btn('Apri','approval',x.id,'small')}</div>`),btn('Tutte','goto','approvals','ghost small'))}${panel('Il prossimo passo',`<div class="quick-actions"><button data-action="new-content">${icon('plus')}Crea un contenuto</button><button data-action="goto" data-id="growth">${icon('search')}Prova la ricerca lead</button><button data-action="new-movement">${icon('wallet')}Registra un movimento</button></div><div class="section">${notice('Gli agenti lavorano su dati DEMO. Tutte le fonti esterne sono scollegate.')}</div>`)}</div>`;}

function clientsView(){const clients=S.overview.clients;return title('Le relazioni, al centro.','Anagrafiche comuni a commerciale, produzione, amministrazione e Fidelity.',btn('Nuova attività','new-client','','primary','plus'))+`<div class="card-grid">${clients.map(c=>{const services=JSON.parse(c.services_json||'[]');return `<article class="module-card"><div class="card-icon">${icon('users')}</div><h3>${e(c.name)}</h3><small>${e(c.industry||'Attività DEMO')} · ${e(c.address||'Indirizzo da completare')}</small><div class="pill-row">${services.slice(0,5).map(x=>badge(serviceName(x),'ink')).join('')}${services.length>5?badge(`+${services.length-5}`):''}</div><p>Stato: ${e(label(c.stage))} · ${e(label(c.risk))}</p><footer>${btn('Apri attività','select-client',c.id,'small')}${btn('Gestisci','edit-client',c.id,'small ghost')}</footer></article>`;}).join('')}</div>`;}
function workCalendar(){const month=S.calendarMonth||localInput(new Date()).slice(0,7),[y,m]=month.split('-').map(Number),first=new Date(y,m-1,1),offset=(first.getDay()+6)%7,days=new Date(y,m,0).getDate(),items=[...S.overview.contents.filter(c=>c.scheduled_at).map(c=>({id:c.id,title:c.title,at:c.scheduled_at,action:'content',kind:'Contenuto'})),...S.overview.tasks.filter(t=>t.due).map(t=>({id:t.id,title:t.title,at:t.due,action:canProduce()?'task':'',kind:'Consegna'}))];return panel('Calendario dell’attività',`<div class="calendar-scroll"><div class="calendar-grid">${['Lun','Mar','Mer','Gio','Ven','Sab','Dom'].map(x=>`<div class="calendar-heading">${x}</div>`).join('')}${Array.from({length:offset},()=>'<div class="calendar-day calendar-blank" aria-hidden="true"></div>').join('')}${Array.from({length:days},(_,i)=>{const key=month+'-'+String(i+1).padStart(2,'0'),entries=items.filter(x=>localInput(x.at).slice(0,10)===key);return `<div class="calendar-day ${key===localInput(new Date()).slice(0,10)?'calendar-today':''}"><time datetime="${key}">${i+1}</time>${entries.map(x=>x.action?`<button class="calendar-item" data-action="${x.action}" data-id="${e(x.id)}"><small>${e(x.kind)} · ${localInput(x.at).slice(11)}</small>${e(x.title)}</button>`:`<div class="calendar-item"><small>${e(x.kind)}</small>${e(x.title)}</div>`).join('')}</div>`;}).join('')}</div></div>`,`<label class="calendar-picker"><span class="sr-only">Mese del calendario</span><input id="calendar-month" type="month" value="${month}" required></label>`,'Date registrate, mostrate nel fuso del dispositivo. Pianificazione interna DEMO, nessuna pubblicazione esterna.');}
function workView(){const o=S.overview;return title('Dal brief al lavoro fatto.','Contenuti, consegne e approvazioni della stessa attività.',canProduce()?btn('Nuovo contenuto','new-content','','primary','plus')+btn('Nuovo lavoro','new-task','','','plus'):'')+`<div class="content-state">${['IDEA','IN PRODUZIONE','DA APPROVARE','APPROVATO','PROGRAMMATO','PUBBLICATO','RIUTILIZZABILE'].map((x,i)=>`${i?'<b>→</b>':''}<span>${x}</span>`).join('')}</div>${notice('Programmare qui organizza il lavoro. La pubblicazione sui canali esterni è disabilitata nella demo.')}${workCalendar()}<div class="card-grid section">${o.contents.map(c=>`<article class="content-card">${badge(c.state)}<h3>${e(c.title)}</h3><small>${e(serviceName(c.service))} · versione ${c.version}</small><div class="content-text">${e(c.body)}</div><div class="source">Fonte: ${e(c.source)}</div><footer><small>${c.scheduled_at?date(c.scheduled_at,true):'Nessuna data programmata'}</small>${btn(canProduce()?'Gestisci':'Leggi','content',c.id,'small')}</footer></article>`).join('')||empty('Il prossimo contenuto parte da qui','Crea un’idea o chiedi allo specialista social una prima bozza.')}</div><div class="section">${panel('Lavori e consegne',table(['Lavoro','Servizio','Scadenza','Stato','Tempo',''],o.tasks.map(t=>[`<strong>${e(t.title)}</strong><small>${e(t.assignee||'Da assegnare')}</small>`,e(serviceName(t.service)),date(t.due),badge(t.status),`${t.actual_minutes} / ${t.estimate_minutes} min`,canProduce()?btn('Aggiorna','task',t.id,'small'):''])))}</div>${canProduce()?`<div class="section">${panel('Memoria dell’attività',list((o.memory||[]),m=>`<div class="list-item"><span class="number">${icon('file')}</span><div class="body"><b>${e(({master:'Scheda master',dna:'DNA e voce',strategy:'Strategia',feedback:'Feedback',report:'Report'})[m.kind]||m.kind)}</b><p>Versione ${m.version} · ${e(m.source)}</p></div>${btn('Apri','memory',m.kind,'small')}</div>`),`<div class="actions">${btn('Versioni','memory-history','','small')}${btn('Esporta memoria','export-memory','','small')}${btn('Nuova scheda','new-memory','','small')}</div>`)}</div>`:''}`;}

function approvalsView(){const items=approvalItems().filter(a=>a.status==='pending');return title('L’ultima parola è vostra.','Ogni decisione conserva autore, data e motivo. Una modifica apre una nuova revisione.')+notice('Approvare una bozza non invia email e non pubblica contenuti: le azioni esterne sono scollegate.')+`<div class="card-grid">${items.map(a=>`<article class="content-card">${badge('pending')}<h3>${e(a.title)}</h3><small>${e(clientName(a.client_id))} · versione ${a.version}</small><div class="content-text">${e(a.body)}</div><footer><small>${e(a.kind==='content'?'Contenuto':a.kind==='growth_message'?'Messaggio Growth':'Campagna Fidelity')}</small>${role()==='collaborator'?badge('Attende cliente o socio'):btn('Rivedi e decidi','approval',a.id,'primary small')}</footer></article>`).join('')||empty('Nessuna decisione in attesa','Le nuove bozze arriveranno qui, pronte per il tuo sguardo.','approval')}</div>`;}
function activityView(){let items=activityItems()||[];if(S.filter)items=items.filter(x=>`${x.action} ${x.detail}`.toLowerCase().includes(S.filter.toLowerCase()));return title('Ogni azione lascia una traccia.','Chi ha fatto cosa, per quale attività e con quali fonti.')+`<div class="toolbar"><input id="local-filter" class="search" placeholder="Cerca un’attività nel registro…" aria-label="Cerca nel registro" value="${e(S.filter)}">${badge(`${items.length} attività`)}</div>${panel('Registro comune',table(['Quando','Attività','Cliente','Dettagli'],items.map(x=>{let d={};try{d=typeof x.detail==='string'?JSON.parse(x.detail):x.detail||{};}catch{}return [date(x.created_at,true),`<strong>${e(x.action)}</strong><small>${e(x.actor_name||'Team BigAnt')}</small>`,e(x.client_id?clientName(x.client_id):'Agenzia'),`<span class="table-text">${e(d.detail||d.reason||d.agent||d.source||'Operazione registrata')}${d.costCents!==undefined?` · ${money(d.costCents)}`:''}</span>`];})))}`;}
function catalogView(){return title('Il catalogo cresce con il metodo.','Ogni servizio ha dati, responsabile, flusso e una condizione precisa per l’attivazione.')+`<div class="card-grid">${S.overview.registry.services.map(s=>`<article class="module-card"><div class="card-icon">${icon(({fidelity:'card',growth:'growth',video:'play',ads:'chart',social:'users',website:'globe'})[s.id]||'book')}</div><h3>${e(s.name)}</h3>${badge(s.status,s.implemented?'green':'')}<p>${e(s.deliverables)}</p><footer><span>${e(s.integration)}</span>${btn('Scheda','service',s.id,'ghost small')}</footer></article>`).join('')}</div>`;}
function connectionsView(){return title('I collegamenti, sotto controllo.','Le integrazioni sono predisposte. Nessun account reale è collegato in questa prova.')+notice('In questa sessione non puoi attivare account, inserire chiavi o avviare servizi a pagamento. Le versioni online di Growth e Fidelity restano indipendenti.',true)+`<div class="card-grid">${S.overview.registry.integrations.map(x=>`<article class="module-card"><div class="card-icon">${icon('link')}</div><h3>${e(x.name)}</h3><p>${e(x.purpose)}</p><footer>${badge('Non collegato')}<span>${e(x.permission)}</span></footer></article>`).join('')}</div>`;}
function clientView(){const o=S.overview,services=activeServices(),metrics=[['Contatti e richieste','growth','Chiamate, WhatsApp, moduli e appuntamenti'],['Social','social','Copertura, interazioni e contenuti'],['Pubblicità','ads','Spesa, risultati e costo per contatto'],['Google e presenza locale','local','Scheda, chiamate e indicazioni'],['Reputazione','presence','Recensioni e risposte'],['Sito e ricerca','website','Visite, ricerche e conversioni']].filter(x=>services.includes(x[1])||(x[1]==='growth'&&services.some(v=>['booking','reception'].includes(v)))||(x[1]==='website'&&services.includes('seo'))||(x[1]==='presence'&&services.includes('local')));return title('Il tuo lavoro, in un colpo d’occhio.',`${clientName(S.clientId)} · I servizi attivi e quello che stiamo costruendo insieme.`)+notice('Stai guardando dati di esempio. Le metriche dei canali non sono disponibili perché le fonti non sono collegate.')+`<div class="stats">${stat('Lavori registrati',o.tasks.length,'Fonte: attività DEMO','work')}${stat('Contenuti pronti da rivedere',o.contents.filter(x=>x.state==='DA APPROVARE').length,'Fonte: calendario DEMO','approval',true)}${stat('Servizi attivi',services.length,'Nel contratto di esempio','book')}${stat('Risultati dei canali','—','Fonti non collegate','chart')}</div><div class="card-grid">${metrics.map(([n,k,desc])=>`<article class="module-card"><h3>${e(n)}</h3><div class="disconnected-number">—</div><p>${e(desc)}</p><footer>${badge('Fonte non collegata')}<span>Nessun dato reale</span></footer></article>`).join('')}</div><div class="grid-two section">${panel('Il prossimo passo insieme',list(o.contents.filter(c=>c.state==='DA APPROVARE').slice(0,4),c=>`<div class="list-item"><span class="number">${icon('approval')}</span><div class="body"><b>${e(c.title)}</b><p>${e(serviceName(c.service))}</p></div>${btn('Apri','content',c.id,'small')}</div>`),btn('Tutti i contenuti','goto','work','small ghost'))}${panel('Chiedi all’agenzia',`<p class="muted">Una risposta basata soltanto sui lavori e sui contenuti di questa attività. Puoi anche aprire una richiesta per il team.</p><form id="ask-form"><div class="field"><label for="ask-question">Di cosa hai bisogno?</label><textarea id="ask-question" name="question" required placeholder="A che punto è il nostro piano contenuti?"></textarea></div><label class="check-field section"><input type="checkbox" name="createTask">Crea anche un lavoro per il team</label><button class="btn primary section" type="submit">Invia la richiesta interna ${icon('arrow')}</button></form><div id="ask-answer" class="preserve section" aria-live="polite"></div>`)}</div><div class="section">${panel('Report e materiali',list((o.memory||[]).filter(m=>m.kind==='report'),m=>`<div class="list-item"><span class="number">${icon('file')}</span><div class="body"><b>Report operativo DEMO</b><p class="preserve">${e(m.content)}</p><small>Fonte: ${e(m.source)}</small></div></div>`))}</div>`;}

const adminData=()=>S.view==='administration'?S.module:S.overview.admin;
function administrationView(){const a=S.module,party=id=>a.counterparties.find(x=>x.id===id)?.name||'—',entity=id=>a.entities.find(x=>x.id===id)?.name||'—';return title('I conti, senza punti ciechi.','Due ditte distinte. Movimenti, scadenze e differenze da verificare insieme.',btn('Registra movimento','new-movement','','primary','plus')+btn('Altre registrazioni','admin-more','','','plus'))+notice('Solo soci · Prima nota gestionale DEMO. Regole fiscali e accantonamenti attendono la conferma del commercialista.')+`<div class="stats">${stat('Incassi del mese',money(a.summary.income_month_cents),'Dati DEMO registrati','wallet')}${stat('Arretrati',money(a.summary.arrears_cents),'Residuo oltre la scadenza','clock',true)}${stat('Bozze da emettere',money(a.summary.draft_invoice_cents),'Nessuna trasmissione allo SDI','file')}${stat('Cosa non torna',a.summary.open_anomalies,'Anomalie aperte da verificare','shield')}</div><div class="grid-two">${a.entities.map(x=>panel(x.name,`<div class="stat-value">${money(x.balance_cents)}</div><p class="muted">Saldo contabile DEMO</p><div class="detail-lines"><div><span>Incassi del mese</span><b>${money(x.income_month_cents)}</b></div><div><span>Uscite del mese</span><b>${money(x.expenses_month_cents)}</b></div><div><span>Prelievi del mese</span><b>${money(x.withdrawals_month_cents)}</b></div></div>${badge('Regole fiscali da confermare')}`)).join('')}</div><div class="section">${panel('Cosa non torna',table(['Priorità','Controllo','Importo','Stato',''],a.anomalies.map(x=>[badge(x.priority,x.priority==='critical'?'red':'orange'),`<strong>${e(x.title)}</strong><small>${e(entity(x.entity_id))}</small>`,money(x.amount_cents),badge(x.status),btn('Verifica','anomaly',x.id,'small')])),btn('Ricalcola controlli','admin-analyze','','small','refresh'))}</div><div class="section">${panel('Prima nota',table(['Data','Causale','Ditta / conto','Controparte','Importo',''],a.movements.map(x=>[date(x.date),`<strong>${e(x.category)}</strong><small>${e(x.document_ref||'Documento da collegare')}</small>`,`<span>${e(entity(x.entity_id))}</span><small>${e(a.accounts.find(c=>c.id===x.account_id)?.name||'—')}</small>`,e(party(x.counterparty_id)),`<span class="balance ${x.direction==='in'?'positive':''}">${x.direction==='in'?'+':'−'}${money(x.amount_cents)}</span>`,(a.reversals||[]).some(r=>r.original_id===x.id||r.reversal_id===x.id)?badge('Storno collegato'):`<div class="actions">${btn('Storna','admin-reverse',x.id,'small')}${x.kind!=='transfer'?btn('Rettifica','admin-correct',x.id,'small'):''}</div>`])),btn('Movimento','new-movement','','small','plus'))}</div><div class="grid-two section">${panel('Documenti e incassi',table(['Bozza','Da incassare','Scadenza'],a.invoices.map(x=>[`<strong>${e(x.number)}</strong><small>${e(party(x.counterparty_id))}</small>`,money(x.remaining_cents),date(x.due_date)])),btn('Nuova bozza','new-invoice','','small','plus'))}${panel('Scadenze e compensi',list(a.obligations,x=>`<div class="list-item"><div class="body"><b>${e(x.title)}</b><p>${e(party(x.counterparty_id))} · ${date(x.due_date)}</p><small>${e(x.document_ref||'Documento da raccogliere')}</small></div><b>${money(x.remaining_cents)}</b></div>`),btn('Nuova scadenza','new-obligation','','small','plus'))}</div><div class="grid-three section">${a.projections.map(x=>panel(`Cassa a ${x.days} giorni`,`<div class="stat-value">${money(x.projected_cents)}</div><div class="detail-lines"><div><span>Entrate attese</span><b>${money(x.expected_income_cents)}</b></div><div><span>Uscite attese</span><b>${money(x.expected_expense_cents)}</b></div></div><small>${e(x.assumption)}</small>`)).join('')}</div><div class="grid-two section">${panel('Conti e quadrature',list(a.accounts,x=>`<div class="list-item"><div class="body"><b>${e(x.name)}</b><p>${e(entity(x.entity_id))}</p></div><b>${money(x.balance_cents)}</b>${btn('Quadra','reconcile',x.id,'small')}</div>`))}${panel('Abbonamenti',list(a.subscriptions,x=>`<div class="list-item"><div class="body"><b>${e(x.name)}</b><p>Rinnovo ${date(x.next_due)} · ogni ${x.interval_months} mesi</p></div><b>${money(x.amount_cents)}</b></div>`),btn('Nuovo','new-subscription','','small','plus'))}</div><div class="section">${panel('Contributo di cassa per cliente',table(['Attività','Incassi','Costi diretti','Contributo'],a.margins.map(x=>[e(x.name),money(x.income_cents),money(x.direct_costs_cents),money(x.cash_contribution_cents)])),'','Il margine completo richiede costo orario, competenza e riparto costi.')}</div>`;}

function growthView(){const g=S.module;const leads=g.leads.filter(l=>!S.filter||`${l.company} ${l.email} ${l.stage}`.toLowerCase().includes(S.filter.toLowerCase()));return title('Le prossime relazioni di BigAnt.','Dalla ricerca alla chiamata, con ogni passaggio nello stesso CRM.',btn('Aggiungi azienda','new-lead','','primary','plus')+btn('Impostazioni','growth-settings','','','grid'))+notice('Ricerca, analisi e conversazioni sono simulate con attività inventate. Nessuna email viene inviata.',true)+`<div class="stats">${stat('Aziende nel radar',g.leads.length,'Contatti di esempio','search')}${stat('Qualificate',g.leads.filter(x=>x.stage==='qualified').length,'Pertinenza commerciale DEMO','growth')}${stat('Bozze da rivedere',g.messages.filter(x=>x.status==='draft').length,'Approvazione umana richiesta','mail',true)}${stat('Budget disponibile',money(g.budget.available),'Budget comune agli agenti','wallet')}</div><div class="panel"><div class="panel-head"><div><h2>Accendi il radar</h2><small>Il simulatore restituisce attività .example, poi ne prepara l’analisi.</small></div>${badge(g.settings.paused?'In pausa':'DEMO abilitata',g.settings.paused?'':'green')}</div><form id="research-form" class="inline-form"><label class="sr-only" for="research-query">Cosa cerchiamo?</label><input id="research-query" name="query" class="search" placeholder="Es. imprese di servizi a Caserta" value="${e(g.settings.sector?g.settings.sector+' '+g.settings.region:'Attività locali a Caserta')}" required><button class="btn primary" type="submit">${icon('search')}Cerca nella demo</button>${btn('Esegui un’attività','growth-run','','','play')}${btn(g.settings.paused?'Attiva DEMO':'Metti in pausa','growth-pause','','',g.settings.paused?'play':'pause')}</form></div><div class="section"><div class="toolbar"><input id="local-filter" class="search" placeholder="Cerca azienda, email o fase…" aria-label="Cerca aziende" value="${e(S.filter)}">${btn('Importa CSV','import-leads','','small')}${btn('Esporta CSV','export-leads','','small')}</div>${panel('Aziende e trattative',table(['Azienda','Fase','Pertinenza','Contatto',''],leads.map(l=>[`<button class="link-button" data-action="lead" data-id="${e(l.id)}">${e(l.company)}</button><small>${e(l.city||l.sector||'DEMO')}</small>`,badge(l.stage),l.score?`${l.score}/100`:'Da analizzare',`${e(l.email||'Email da aggiungere')}<small>${l.suppressed?'Contatto interrotto':l.consent==='marketing'?'Consenso marketing registrato':l.consent==='request'?'Richiesta di risposta':'Autorizzazione da verificare'}</small>`,`<div class="actions">${btn('Analizza','analyze-lead',l.id,'small')}${btn('Bozza','draft-lead',l.id,'small')}</div>`])))}</div><div class="grid-two section">${panel('Bozze e conversazioni',list(g.messages.slice(0,12),m=>`<div class="list-item"><span class="number">${icon('mail')}</span><div class="body"><b>${e(m.subject)}</b><p>${e(m.company)} · ${m.direction==='in'?'Risposta DEMO':'Messaggio commerciale'}</p><div class="pill-row">${badge(m.status)}</div></div>${btn('Apri','message',m.id,'small')}</div>`))}${panel('Appuntamenti',list(g.meetings,m=>`<div class="list-item"><span class="number">${icon('calendar')}</span><div class="body"><b>${e(m.company)}</b><p>${date(m.start,true)}</p>${badge(m.status)}</div>${m.status==='simulated_booked'?btn('Annulla','cancel-meeting',m.id,'small'):['pending','uncertain'].includes(m.status)?btn('Verifica esito','reconcile-meeting',m.id,'small'):''}</div>`),'','Calendario locale DEMO. Nessun invito Google.')}</div><div class="section">${panel('Attività del motore Growth',table(['Attività','Quando','Stato','Esito',''],g.jobs.slice(0,15).map(j=>[e(({research:'Ricerca',analyze:'Analisi',draft:'Bozza',sync:'Conversazioni',reconcile:'Verifica messaggio',reconcileMeeting:'Verifica appuntamento'})[j.type]||j.type),date(j.created,true),badge(j.status),`<span class="table-text">${e(j.error||'—')}</span>`,j.status==='failed'?btn('Riprova','retry-growth',j.id,'small'):''])),btn('Esegui prossima','growth-run','','small','play'))}</div>`;}

function fidelityView(){const f=S.module,manager=role()!=='collaborator',p=f.programs[0],m=f.members.find(x=>x.programId===p?.id);return title('Un buon motivo per tornare.','Programmi fedeltà, iscritti, premi e campagne per l’attività selezionata.',manager?btn('Nuovo programma','new-program','','primary','plus')+btn('Nuovo iscritto','new-member','','','plus')+btn('Regolamento','fidelity-policies','','','file'):'')+`<div class="stats">${stat('Iscritti',f.metrics.members,'Tessere DEMO','users')}${stat('Programmi attivi',f.metrics.programs,'Timbri, punti e coupon','card')}${stat('Premi riscattati',f.metrics.redemptions,'Movimenti registrati','star',true)}${stat('Consensi marketing',f.metrics.marketingMembers,'Solo iscritti autorizzati','shield')}</div><div class="grid-wide"><div class="fidelity-card"><div class="label">${e(clientName(S.clientId))} / FIDELITY DEMO</div><h2>${e(p?.name||'La prossima visita conta.')}</h2><p>${e(p?.rewardName||'Crea il primo programma per la tua attività.')}</p><div class="stamps">${Array.from({length:Math.min(p?.rewardThreshold||8,12)},(_,i)=>`<span class="stamp ${i<(m?.balance||0)?'filled':''}">${i<(m?.balance||0)?'✓':i+1}</span>`).join('')}</div><small>${m?`Anteprima di ${e(m.name)} · saldo ${m.balance}`:'Anteprima programma'} · Apple e Google Wallet non collegati</small></div>${panel('Programmi',list(f.programs,x=>`<div class="list-item"><div class="body"><b>${e(x.name)}</b><p>${e(label(x.type))} · premio a ${x.rewardThreshold} · ${e(x.rewardName)}</p><small>${x.memberCount} iscritti</small></div>${btn('Dettagli','program',x.id,'small')}</div>`))}</div><div class="section">${panel('Iscritti e tessere',table(['Iscritto','Programma','Saldo','Consenso',''],f.members.map(x=>[`<strong>${e(x.name)}</strong><small>${e(x.email)}</small>`,e(x.programName),`<strong>${x.balance}</strong><small>${x.availableRewards} premi disponibili</small>`,badge(x.marketingConsent?'Autorizzato':'Non presente',x.marketingConsent?'green':''),`<div class="actions">${btn('Movimento','member-transaction',x.id,'small')}${btn('Tessera','member',x.id,'small')}</div>`])),`<div class="actions">${btn('Cerca tessera','scan','','small','search')}${manager?btn('Esporta','export-members','','small'):''}</div>`)}</div><div class="section">${panel('Registro timbri e punti',table(['Quando','Iscritto','Operazione','Quantità','Saldo',''],f.transactions.map(x=>[date(x.createdAt,true),e(x.memberName),e(label(x.type)),`${x.amount>0?'+':''}${x.amount}`,x.balanceAfter,manager&&x.type!=='reversal'&&!x.reversed?btn('Storna','reverse',x.id,'small'):''])))}</div>${manager?`<div class="grid-two section">${panel('Campagne',list(f.campaigns,x=>`<div class="list-item"><div class="body"><b>${e(x.name)}</b><p>${e(x.title)} · ${x.recipientCount} destinatari preparati</p>${badge(x.status)}</div>${btn('Apri','campaign',x.id,'small')}</div>`),btn('Nuova bozza','new-campaign','','small','plus'))}${panel('Ritorno clienti',list(f.automations,x=>`<div class="list-item"><div class="body"><b>${e(x.name)}</b><p>Dopo ${x.inactiveDays} giorni · ${x.active?'Attivo in preparazione':'In pausa'}</p></div>${btn('Prepara','run-fidelity-auto',x.id,'small')}${btn(x.active?'Pausa':'Attiva','toggle-fidelity-auto',x.id,'small ghost')}</div>`),btn('Nuova regola','new-fidelity-auto','','small','plus'))}</div>`:''}<div class="section">${notice('Wallet scollegati: le campagne preparano destinatari e approvazioni; non inviano notifiche e non rilasciano tessere Apple o Google reali.')}</div>`;}

function agentsView(){const a=S.module;return title('Uno sciame, una sola regia.','Ogni agente ha un compito preciso, una fonte e un limite. Le decisioni importanti restano ai soci.',btn(a.paused?'Riattiva gli agenti':'Metti in pausa','agents-pause','','',a.paused?'play':'pause')+btn('Esegui un giro','agents-tick','','primary','play'))+`${S.overview.workerError?notice('Il giro automatico richiede una verifica: '+S.overview.workerError,true):''}${Object.entries(a.moduleErrors||{}).filter(([,error])=>error).map(([module,error])=>notice((module==='growth'?'Growth':'Fidelity')+' · Attività da verificare: '+error,true)).join('')}<div class="stats">${stat('Specialisti disponibili',a.definitions.filter(x=>x.status==='implemented').length,'Regole locali DEMO','agents')}${stat('Attività in coda',a.jobs.filter(x=>x.status==='queued').length,'Persistenti e verificabili','clock')}${stat('Spesa simulazioni',money(a.budget.usedCents),'Nessun provider a pagamento','wallet')}${stat('Disponibile nel mese',money(a.budget.availableCents),`Tetto ${money(a.budget.capCents)}`,'shield',true)}</div>${notice(a.notifications)}<div class="card-grid">${a.definitions.map(x=>`<article class="module-card"><div class="card-icon">${icon(x.id==='director'?'growth':x.id==='administration'?'wallet':'agents')}</div><h3>${e(x.name)}</h3>${badge(x.status,x.status==='implemented'?'green':'')}<p>${e(x.purpose)}</p><footer><span>DEMO · € 0,00</span>${x.status==='implemented'?btn('Avvia','run-agent',x.id,'small'):x.status==='module'?btn('Apri Growth','goto','growth','small'):badge('SOP da completare')}</footer></article>`).join('')}</div><div class="grid-two section">${panel('Automatismi pianificati',list(a.schedules,x=>`<div class="list-item"><span class="number">${icon('calendar')}</span><div class="body"><b>${e(a.definitions.find(d=>d.id===x.agent)?.name||x.agent)}</b><p>${e(clientName(x.client_id))} · ${e(({daily:'Ogni giorno', 'weekly-monday':'Lunedì', 'weekly-friday':'Venerdì',monthly:'Primo del mese'})[x.trigger]||'Su evento')}</p><small>${x.next_at?`Prossimo giro ${date(x.next_at,true)}`:'In attesa dell’evento'}</small></div>${btn(x.enabled?'Pausa':'Attiva','toggle-schedule',x.id,'small')}</div>`),btn('Nuova regola','new-schedule','','small','plus'))}${panel('Budget del pilota',`<div class="stat-value">${money(a.budget.capCents)}</div><p class="muted">Tetto mensile condiviso da tutti i reparti</p><div class="detail-lines"><div><span>Quote fisse e riserva</span><b>${money(a.budget.fixedCents)}</b></div><div><span>Agenti e ricerche</span><b>${money(a.budget.usedCents)}</b></div><div><span>Ancora disponibile</span><b>${money(a.budget.availableCents)}</b></div></div>${btn('Modifica ripartizione','budget','','small')}`)}</div><div class="section">${panel('Giri dello sciame',table(['Agente','Attività','Stato','Risultato',''],a.jobs.map(x=>[e(a.definitions.find(d=>d.id===x.agent)?.name||x.agent),e(clientName(x.client_id)),badge(x.status),`<span class="table-text">${e(x.result?.summary||x.error||'In attesa di esecuzione')}</span>`,x.result?btn('Leggi','agent-result',x.id,'small'):x.status==='failed'?btn('Riprova','retry-agent',x.id,'small'):''])))}</div>`;}

async function go(view){$('#dialog').close();S.view=view;S.filter='';history.replaceState(null,'','#'+view);await load();}
async function download(path,name,type='text/csv;charset=utf-8'){const value=await api(path);const url=URL.createObjectURL(new Blob([value],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const textField=(name,label,value='',full=false)=>({name,label,value,full,required:true});
const selectField=(name,label,opts,value='')=>({name,label,type:'select',options:opts,value,required:true});
const numberField=(name,label,value,min=0,step='1')=>({name,label,value,type:'number',min,step,required:true});
const areaField=(name,label,value='')=>({name,label,value,type:'textarea',full:true,required:true});
function demoEmail(value){if(!String(value).toLowerCase().endsWith('.example'))throw Error('Per la prova usa un indirizzo inventato che termina con .example.');}
