let cameraStream=null,cameraTimer=null;
function stopCamera(){clearTimeout(cameraTimer);cameraTimer=null;cameraStream?.getTracks().forEach(t=>t.stop());cameraStream=null;}
ACTIONS.camera=async()=>{stopCamera();if(!('BarcodeDetector' in window)||!navigator.mediaDevices?.getUserMedia)throw Error('Lettura QR non supportata: usa il codice manuale.');const video=$('#camera-video'),status=$('#camera-status');try{cameraStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'},audio:false});video.srcObject=cameraStream;video.hidden=false;await video.play();status.textContent='Inquadra il codice della tessera DEMO.';const detector=new BarcodeDetector({formats:['qr_code']});async function detect(){if(!cameraStream||!$('#dialog').open)return;try{const codes=await detector.detect(video);if(codes[0]?.rawValue){stopCamera();const f=$('#modal-form');f.elements.code.value=codes[0].rawValue;video.hidden=true;status.textContent='Codice letto. Premi Cerca per aprire la tessera.';return;}}catch{}cameraTimer=setTimeout(detect,400);}detect();}catch(error){stopCamera();throw Error('Fotocamera non disponibile. Puoi incollare il codice della tessera.');}};
$('#dialog').addEventListener('close',stopCamera);

document.addEventListener('click',async event=>{const view=event.target.closest('[data-view]');if(view){event.preventDefault();await go(view.dataset.view);return;}const button=event.target.closest('[data-action]');if(!button)return;event.preventDefault();const action=ACTIONS[button.dataset.action];if(!action)return;button.disabled=true;try{await action(button.dataset.id);}catch(error){toast(error.message,true);}finally{if(button.isConnected)button.disabled=false;}});
document.addEventListener('submit',async event=>{const f=event.target;if(!['modal-form','ask-form','research-form','public-join','public-book','public-inquiry'].includes(f.id))return;event.preventDefault();const submit=f.querySelector('button[type=submit]'),errorBox=f.querySelector('.form-error');if(submit)submit.disabled=true;if(errorBox)errorBox.hidden=true;try{const fd=new FormData(f),b=Object.fromEntries(fd);if(f.id==='modal-form')await formHandler(fd);
else if(f.id==='ask-form'){const result=await mutate('/api/production/ask',{question:b.question,createTask:fd.has('createTask')});$('#ask-answer').textContent=result.answer+(result.taskId?'\n\nLa richiesta è stata aggiunta ai lavori del team.':'');}
else if(f.id==='research-form'){if(S.module.settings.paused)await mutate('/api/growth/settings',{paused:false});await mutate('/api/growth/jobs',{type:'research',query:b.query});const result=await mutate('/api/growth/jobs/run');toast(result.job?.status==='failed'?result.job.error:'Ricerca DEMO eseguita. Le analisi sono in coda.');await load();}
else if(f.id==='public-join'){demoEmail(b.email);const r=await api('/api/fidelity/public/join/'+encodeURIComponent(publicContext.slug),{method:'POST',body:{...b,name:b.name.includes('DEMO')?b.name:b.name+' · DEMO',acceptTerms:fd.has('acceptTerms'),marketingConsent:fd.has('marketingConsent')},scoped:false});location.href=r.cardUrl;}
else if(f.id==='public-book'){const r=await api('/api/growth/public/book/'+publicContext.token,{method:'POST',body:b,scoped:false});publicShell('Appuntamento DEMO registrato',`<p>${date(r.start,true)} · Nessun invito esterno è stato inviato.</p>${badge('Confermato nella simulazione','green')}`);}
else if(f.id==='public-inquiry'){demoEmail(b.email);await api('/api/growth/public/inquiry',{method:'POST',body:{...b,privacyAcknowledged:fd.has('privacyAcknowledged'),marketing:fd.has('marketing')},scoped:false});publicShell('Richiesta DEMO registrata','<p>È disponibile nel CRM di BigAnt. Nessuna email viene inviata.</p>');}
}catch(error){if(errorBox){errorBox.textContent=error.message;errorBox.hidden=false;}else toast(error.message,true);}finally{if(submit?.isConnected)submit.disabled=false;}});
document.addEventListener('change',async event=>{try{if(event.target.id==='calendar-month'){if(/^\d{4}-\d{2}$/.test(event.target.value)){S.calendarMonth=event.target.value;render();}return;}if(event.target.id==='client-picker'){S.clientId=event.target.value;S.filter='';await load();}if(event.target.id==='public-consent'){const desired=event.target.checked;try{await api('/api/fidelity/public/cards/'+publicContext.token+'/consent',{method:'PATCH',body:{marketingConsent:desired},scoped:false});toast('Preferenza aggiornata');}catch(error){event.target.checked=!desired;throw error;}}if(event.target.name==='entityId'&&$('#modal-form [name=accountId]')){const account=$('#modal-form [name=accountId]');account.innerHTML=adminData().accounts.filter(x=>x.entity_id===event.target.value).map(x=>`<option value="${e(x.id)}">${e(x.name)}</option>`).join('');}if(event.target.name==='invoiceId'&&event.target.value){const a=adminData(),i=a.invoices.find(x=>x.id===event.target.value),f=$('#modal-form');f.elements.entityId.value=i.entity_id;f.elements.entityId.dispatchEvent(new Event('change',{bubbles:true}));f.elements.counterpartyId.value=i.counterparty_id;f.elements.amountEuros.value=(i.remaining_cents/100).toFixed(2);f.elements.kind.value='income';if(f.elements.obligationId)f.elements.obligationId.value='';if(f.elements.subscriptionId)f.elements.subscriptionId.value='';}if(['obligationId','subscriptionId'].includes(event.target.name)&&event.target.value){const a=adminData(),isObligation=event.target.name==='obligationId',x=(isObligation?a.obligations:a.subscriptions).find(x=>x.id===event.target.value),f=$('#modal-form');f.elements.entityId.value=x.entity_id;f.elements.entityId.dispatchEvent(new Event('change',{bubbles:true}));f.elements.counterpartyId.value=x.counterparty_id||'';f.elements.amountEuros.value=((isObligation?x.remaining_cents:x.amount_cents)/100).toFixed(2);f.elements.kind.value=x.kind==='owner_agreement'?'withdrawal':'expense';f.elements.invoiceId.value='';f.elements[isObligation?'subscriptionId':'obligationId'].value='';}}catch(error){toast(error.message,true);}});
let filterTimer;document.addEventListener('input',event=>{if(event.target.id!=='local-filter')return;const value=event.target.value,position=event.target.selectionStart;clearTimeout(filterTimer);filterTimer=setTimeout(()=>{S.filter=value;render();const field=$('#local-filter');field?.focus();field?.setSelectionRange(position,position);},180);});
$('#dialog').addEventListener('click',event=>{if(event.target===$('#dialog')){const r=$('#dialog').getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)$('#dialog').close();}});
setInterval(async()=>{if(!S.session?.user||!['agents','growth'].includes(S.view)||$('#dialog').open||document.hidden||document.activeElement?.matches('input,textarea,select,[contenteditable=true]')||S.refreshing||Date.now()-(S.lastRefresh||0)<7500)return;S.refreshing=true;try{await load();}finally{S.refreshing=false;}},8000);
async function start(){try{if(await publicPage())return;S.session=await api('/api/session',{scoped:false});if(!S.session.user)return login();S.view=location.hash.slice(1)|| (isOwner()?'direction':role()==='client'?'client':'work');await load();}catch(error){publicShell('Non riesco ad aprire questa pagina',`${notice(error.message)}<a class="btn" href="/">Torna al workspace</a>`);}}
start();
